final class UITestHarnessTests: XCTestCase {

    func testRun() throws {
        let cmdPath = "/tmp/uitest/cmd.json"
        let resultPath = "/tmp/uitest/result.txt"
        var log = ""
        func note(_ s: String) {
            log += s + "\n"
            try? log.write(toFile: resultPath, atomically: true, encoding: .utf8)
        }

        let data = try Data(contentsOf: URL(fileURLWithPath: cmdPath))
        let obj = try JSONSerialization.jsonObject(with: data) as! [String: Any]
        let actions = obj["actions"] as! [[String: Any]]

        for (i, action) in actions.enumerated() {
            let type = action["type"] as! String
            note("action \(i): \(type)")
            switch type {
            case "wait":
                let s = (action["seconds"] as? Double) ?? 1.0
                Thread.sleep(forTimeInterval: s)
            case "dump":
                let bundleId = (action["bundleId"] as? String) ?? "im.vector.app"
                let path = action["path"] as! String
                let app = XCUIApplication(bundleIdentifier: bundleId)
                let desc = app.debugDescription
                try desc.write(toFile: path, atomically: true, encoding: .utf8)
                note("dumped \(bundleId) -> \(path)")
            case "tap":
                let bundleId = (action["bundleId"] as? String) ?? "im.vector.app"
                let predStr = action["predicate"] as! String
                let timeout = (action["timeout"] as? Double) ?? 10.0
                let app = XCUIApplication(bundleIdentifier: bundleId)
                let pred = NSPredicate(format: predStr)
                let query = app.descendants(matching: .any).matching(pred)
                let m = query.firstMatch
                if m.waitForExistence(timeout: timeout) {
                    m.tap()
                    note("tapped: \(predStr)")
                } else {
                    note("NOT_FOUND: \(predStr)")
                }
            case "tapIfPresent":
                let bundleId = (action["bundleId"] as? String) ?? "im.vector.app"
                let predStr = action["predicate"] as! String
                let timeout = (action["timeout"] as? Double) ?? 2.0
